import importlib
import math
import os
import warnings

import numpy as np
import pandas as pd
import pytest

from pandarallel import pandarallel
import pandarallel.core as pandarallel_core

MEMORY_FS_EXISTS = os.path.isdir("/dev/shm")


@pytest.fixture
def df_size():
    return 50


@pytest.fixture
def func_dataframe_apply_axis_0():
    def func(x):
        return x.sum()

    return func


@pytest.fixture
def func_dataframe_apply_axis_1():
    def func(x):
        return x.iloc[0] ** 2 + x.iloc[1] ** 2

    return func


@pytest.fixture
def func_dataframe_applymap():
    return lambda x: x**2


@pytest.fixture
def func_series_apply():
    return lambda x: x**2


@pytest.fixture
def func_series_map():
    return lambda x: math.log10(x)


@pytest.fixture
def func_dataframe_groupby_apply():
    def func(df):
        return df.b - df.b.mean()

    return func


@pytest.fixture
def func_series_rolling_apply():
    return lambda x: x.sum()


@pytest.fixture
def func_dataframe_groupby_rolling_apply():
    return lambda x: x.sum()


@pytest.fixture
def func_dataframe_groupby_expanding_apply():
    return lambda x: x.sum()


@pytest.fixture(
    params=[
        (progress_bar, use_memory_fs)
        for progress_bar in (False, True)
        for use_memory_fs in ((False, True) if MEMORY_FS_EXISTS else (False,))
    ]
)
def pandarallel_init(request):
    progress_bar, use_memory_fs = request.param
    pandarallel.initialize(
        progress_bar=progress_bar, use_memory_fs=use_memory_fs, nb_workers=2
    )


def test_dataframe_apply_axis_0(
    df_size, pandarallel_init, func_dataframe_apply_axis_0
):
    df = pd.DataFrame(
        dict(a=np.random.randint(1, 8, df_size), b=np.random.rand(df_size))
    )
    df.index = [item / 10 for item in df.index]

    res = df.apply(func_dataframe_apply_axis_0, axis=0)
    res_parallel = df.parallel_apply(func_dataframe_apply_axis_0, axis=0)
    assert res.equals(res_parallel)


