def test_memory_fs_root_environment_variable(monkeypatch):
    monkeypatch.setenv("MEMORY_FS_ROOT", "/test")
    importlib.reload(pandarallel_core)
    assert pandarallel_core.MEMORY_FS_ROOT == "/test"

    # Restore the module to its original state so other tests are unaffected
    monkeypatch.delenv("MEMORY_FS_ROOT", raising=False)
    importlib.reload(pandarallel_core)
    assert pandarallel_core.MEMORY_FS_ROOT == "/dev/shm"


def test_dataframe_apply_axis_1_raises(df_size, pandarallel_init):
    df = pd.DataFrame(
        dict(a=np.random.randint(1, 8, df_size), b=np.random.rand(df_size))
    )

    def func(x):
        raise ValueError("boom")

    with pytest.raises(ValueError):
        df.parallel_apply(func, axis=1)
